package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.OperacaoDtos.DespesaRequest; import br.com.tapeteskalke.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/despesas") public class DespesaController { private final DespesaService service; private final PermissionService permissions; public DespesaController(DespesaService service,PermissionService permissions){this.service=service;this.permissions=permissions;} @GetMapping public ApiResponse<?> list(){permissions.action("relatorios_visualizar");return ApiResponse.ok(service.list());} @PostMapping public ResponseEntity<ApiResponse<?>> create(@Valid @RequestBody DespesaRequest r){permissions.action("despesas_criar");return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.create(r)));} }